# The two bowl footprints are aligned at a low release height.
# I will release, lift clear, and return the right arm home to inspect whether they nest stably.
obs = get_observation()
state = obs['state']
release_action = {'right_ee_pose': state['right_ee_pose'], 'left_ee_pose': state['left_ee_pose'], 'right_ee_joint_state': [1.0], 'left_ee_joint_state': state['left_ee_joint_state']}
ended = False
for i in range(10):
    obs, reward, terminated, truncated, info = step(release_action)
    if terminated or truncated:
        ended = True
        break
if not ended:
    obs, used, result = servo_translate('right', [-0.130, -0.285, 1.085], 1.0, max_steps=25)
    print('retreat', result, used)
    ended = result == 'ended'
if not ended:
    for i in range(35):
        obs, reward, terminated, truncated, info = step(home_joints)
        if terminated or truncated:
            break
print('final', reward, terminated, truncated, obs['state'])

